        "type": "object",
        "properties": {
          "delta_cents": {
            "type": "number",
            "description": "How many cents the mid will MOVE over the next five minutes. Negative for down, 0 for no move (the most common answer). This is the CHANGE, not the price level."
          },
          "half_width_cents": {
            "type": "number",
            "description": "Half the width of the tightest two-sided market you would stand behind, in cents. Typically current spread plus 1-2 cents for uncertainty."
          },
          "confidence": {
            "type": "number",
            "description": "0-1. How sure you are."
          },
          "driver": {
            "type": "string",
            "description": "The primary reason: 'still absorbing recent goal', 'thin book reversion', 'late-game time decay', or 'stable/no catalyst'."
          },
          "falsifier": {
            "type": "string",
            "description": "What would prove this wrong within 5 minutes."
          }
        },
        "required": [
          "delta_cents",
          "half_width_cents",
          "confidence",
          "driver",
          "falsifier"
